function isValidIdentifier(value) {
  if (typeof value !== 'string') return false;
  const v = value.trim();
  if (!v) return false;
  // Legacy Mongo ObjectId
  if (/^[0-9a-fA-F]{24}$/.test(v)) return true;
  // Current CRM UUID
  if (/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/.test(v)) return true;
  // Allow generic non-empty ids used by older/external study selectors
  return true;
}

function formatFileSize(bytes) {
  if (!bytes || bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

function extractExtension(value) {
  const raw = String(value || '');
  if (!raw) return '';
  try {
    const cleaned = raw.split('?')[0];
    const name = cleaned.split('/').pop() || cleaned;
    const parts = name.split('.');
    if (parts.length < 2) return '';
    return String(parts.pop() || '').toLowerCase();
  } catch {
    return '';
  }
}

const isDraftStatus = (status) =>
  String(status || 'Draft').trim().toLowerCase() === 'draft';

const isOxfordRecIrbName = (name) => {
  const n = String(name || '').toLowerCase();
  return (
    (n.includes('south central') && n.includes('oxford') && n.includes('research ethics committee')) ||
    (n.includes('hra') && n.includes('oxford') && n.includes('rec'))
  );
};

const isNccJapanIrbName = (name) => {
  const n = String(name || '').toLowerCase();
  return n.includes('national cancer center') && n.includes('japan');
};

