// Submission templates from MongoDB (GET /notification-templates).
// The hard-coded lists above remain as an offline fallback; on a successful
// fetch the server registry drives the step-1 cards and per-type document sets.
// ---------------------------------------------------------------------------
const WORKFLOW_FALLBACK_DOCUMENTS = {
  'Amendment / Modification Package': AMENDMENT_MODIFICATION_DOCUMENTS,
  'Continuing Review / (Annual Renewal)': CONTINUING_REVIEW_DOCUMENTS,
  'Safety Report Submission / Package': SAFETY_REPORT_DOCUMENTS,
  'Study Closure Package': STUDY_CLOSURE_DOCUMENTS,
  'Protocol Deviation / Violation Package': PROTOCOL_DEVIATION_VIOLATION_DOCUMENTS,
};

// Mongo/JSON can't store Infinity — the registry uses >= 10000 to mean unlimited.
const normalizeWorkflowDoc = (d) => ({
  ...d,
  max_files:
    typeof d.max_files === 'number' && d.max_files >= 10000 ? Infinity : d.max_files,
  uploadAllowed: d.uploadAllowed ?? true,
});

let _submissionTemplatesCache = null;
let _submissionTemplatesPromise = null;
function loadSubmissionTemplates() {
  if (_submissionTemplatesCache) return Promise.resolve(_submissionTemplatesCache);
  if (!_submissionTemplatesPromise) {
    _submissionTemplatesPromise = sitePackageService
      .getNotificationTemplates()
      .then((resp) => {
        const data = resp?.data || resp || {};
        _submissionTemplatesCache = {
          submissionTypes: Array.isArray(data.submissionTypes) ? data.submissionTypes : [],
          workflowDocuments: data.workflowDocuments && typeof data.workflowDocuments === 'object' ? data.workflowDocuments : {},
        };
        return _submissionTemplatesCache;
      })
      .catch((err) => {
        console.warn('[SitePackages] Falling back to built-in submission templates:', err?.message);
        _submissionTemplatesPromise = null; // allow retry on next mount
        return { submissionTypes: [], workflowDocuments: {} };
      });
  }
  return _submissionTemplatesPromise;
}

