  const canGenerateForDoc = (doc) => {
    const docKey = getDocTypeKey(doc);
    if (!GENERATE_ALLOWED_TYPES.has(docKey)) return false;
    
    const raw = String(doc?.type || doc?.key || doc?.documentType || doc?.name || "").toLowerCase().trim();
    if (raw.includes("costing template") || raw.includes("clinical trial agreement") || raw.includes("clinical trial contract") || raw.includes("cta")) {
      return false;
    }
    
    return true;
  };

  const isCoverLetterRequirement = (doc) => {
    const key = getDocTypeKey(doc);
    if (key && COVER_LETTER_TYPES.has(String(key).toLowerCase())) return true;
    const name = String(doc?.name || '').toLowerCase();
    return name.includes('cover letter');
  };

  const hydrateUploadedDocumentsFromPackage = (pkg) => {
    const byName = {};
    let hydratedProtocolMetadata = null;
    for (const d of pkg?.documents || []) {
      const reqName = d.name;
      if (!reqName) continue;
      const src = d.source || 'upload';
      const row = {
        uploaded: true,
        fileUrl: d.fileUrl,
        fileSize: d.fileSize,
        mimeType: d.mimeType || 'application/octet-stream',
        source: src,
        tmfDocumentId: d.tmfDocumentId,
        sourceDocumentId: d.sourceDocumentId,
        sourceTitle: d.sourceTitle,
        type: d.type,
        version: d.version,
        docxFileUrl: d.docxFileUrl,
        pdfFileUrl: d.pdfFileUrl,
        protocolMetadata: d.protocolMetadata,
      };
      if (String(src).toUpperCase() === 'ISF') {
        row.source = 'ISF';
        row.sourceUrl = d.fileUrl;
      }
      if (!byName[reqName]) byName[reqName] = [];
      byName[reqName].push(row);
      const typeKey = getDocTypeKey(d);
      if (!hydratedProtocolMetadata && isProtocolDocType(typeKey) && d?.protocolMetadata) {
        hydratedProtocolMetadata = d.protocolMetadata;
      }
    }
    if (hydratedProtocolMetadata && typeof hydratedProtocolMetadata === 'object') {
      setProtocolMetadata((prev) => ({
        ...prev,
        protocol_number: String(hydratedProtocolMetadata.protocol_number || ''),
        study_title: String(hydratedProtocolMetadata.study_title || ''),
        version: String(hydratedProtocolMetadata.version || ''),
        date: String(hydratedProtocolMetadata.date || ''),
        study_description: String(hydratedProtocolMetadata.study_description || ''),
      }));
    }
    return byName;
  };

  const buildDocumentsPayloadForSave = () => {
    return requiresDocumentUpload
      ? Object.entries(uploadedDocuments || {}).flatMap(([docName, val]) => {
          const reqDoc = allDocuments.find((d) => d.name === docName) || { name: docName };
          const docTypeKey = getDocTypeKey(reqDoc) || undefined;
          return toDocRows(val)
            .filter((r) => r?.fileUrl)
            .map((r) => ({
              name: docName,
              fileUrl: r.fileUrl,
              ...(r.pdfFileUrl ? { pdfFileUrl: r.pdfFileUrl } : {}),
              ...(r.docxFileUrl ? { docxFileUrl: r.docxFileUrl } : {}),
              ...(r.version ? { version: r.version } : {}),
              fileSize: r.fileSize || r.file?.size || 0,
              mimeType: r.mimeType || r.file?.type || "application/octet-stream",
              source: r.source || "upload",
              ...(r.sourceDocumentId ? { sourceDocumentId: r.sourceDocumentId } : {}),
              ...(r.sourceTitle ? { sourceTitle: r.sourceTitle } : {}),
              ...(r.tmfDocumentId ? { tmfDocumentId: r.tmfDocumentId } : {}),
              ...(docTypeKey ? { type: docTypeKey } : {}),
              ...(isProtocolDocType(docTypeKey) && protocolMetadata
                ? {
                    protocolMetadata: {
                      protocol_number: protocolMetadata.protocol_number || null,
                      study_title: protocolMetadata.study_title || null,
                      version: protocolMetadata.version || null,
                      date: protocolMetadata.date || null,
                      study_description: protocolMetadata.study_description || null,
                    },
                  }
                : {}),
            }));
        })
      : [];
  };

  const ensurePackageForCoverLetterEdit = async () => {
    if (effectivePackageId) return effectivePackageId;
    if (!resolvedStudyId || !resolvedSiteId) {
      throw new Error('Select study and site before editing cover letter.');
    }
    if (!irb?.id) {
      throw new Error('No IRB mapped. Configure Site Profile first.');
    }

    const values = form.getValues();
    const payload = {
      study: resolvedStudyId,
      site: resolvedSiteId,
      irb_id: irb.id,
      ethicsBoard: irb.name,
      packageName: values?.packageName,
      description: values?.description,
      priority: values?.priority,
      submissionType,
      expectedSubmissionDate: values?.expectedSubmissionDate ? values.expectedSubmissionDate : null,
      contactPerson: values?.contactPerson,
      notes: values?.notes,
      documents: buildDocumentsPayloadForSave(),
    };

    const createResp = onSubmit
      ? await onSubmit(payload)
      : await sitePackageService.createSitePackage(payload);
    const created = createResp?.data?.sitePackage || createResp?.sitePackage || createResp?.data;
    const packageId = created?._id;
    if (!packageId) {
      throw new Error('Failed to auto-create package for cover-letter editing.');
    }
    setCreatedPackageId(packageId);
    setExistingPackageStatus(created?.status || 'Draft');
    return packageId;
  };

  const refreshExistingPackageDocuments = async () => {
    if (!effectivePackageId || !resolvedStudyId || !resolvedSiteId) return;
    setRefreshingAfterEdit(true);
    try {
      const resp = await sitePackageService.getById(effectivePackageId, {
        study: resolvedStudyId,
        site: resolvedSiteId,
      });
      const pkg = resp?.data;
      if (!pkg) return;
      setUploadedDocuments(hydrateUploadedDocumentsFromPackage(pkg));
    } catch (e) {
      toast({
        title: 'Refresh failed',
        description: e?.message || 'Could not refresh updated cover letter.',
        variant: 'destructive',
      });
    } finally {
      setRefreshingAfterEdit(false);
    }
  };

  const getCoverLetterStatusSnapshot = async (packageId, docName) => {
    const resp = await sitePackageService.getCoverLetterOnlyOfficeStatus({
      packageId,
      studyId: resolvedStudyId,
      siteId: resolvedSiteId,
      documentName: docName,
    });
    return resp?.data || resp || null;
  };

  const waitForCoverLetterProcessing = async ({
    packageId,
    docName,
    baselineVersion,
    baselineUpdatedAt,
    timeoutMs = 25000,
    intervalMs = 1000,
  }) => {
    const startedAt = Date.now();
    while (Date.now() - startedAt < timeoutMs) {
      try {
        const status = await getCoverLetterStatusSnapshot(packageId, docName);
        const currentVersion = Number(status?.version || 0);
        const currentUpdatedAtMs = status?.updatedAt ? Date.parse(String(status.updatedAt)) : 0;
        const baselineUpdatedAtMs = baselineUpdatedAt ? Date.parse(String(baselineUpdatedAt)) : 0;
        if (
          (Number.isFinite(currentVersion) && currentVersion > Number(baselineVersion || 0)) ||
          (currentUpdatedAtMs > 0 && baselineUpdatedAtMs > 0 && currentUpdatedAtMs > baselineUpdatedAtMs)
        ) {
          return true;
        }
      } catch {
        // Polling is best-effort; continue retrying until timeout.
      }
      await new Promise((resolve) => setTimeout(resolve, intervalMs));
    }
    return false;
  };

  const handleCloseAndRefreshCoverLetter = async () => {
    if (!effectivePackageId || !resolvedStudyId || !resolvedSiteId) {
      await refreshExistingPackageDocuments();
      setCoverLetterEditorOpen(false);
      return;
    }

    setClosingCoverLetterEditor(true);
    try {
      const baseline = await getCoverLetterStatusSnapshot(effectivePackageId, coverLetterEditingName);
      const saveRequested = Boolean(coverLetterEditorRef.current?.requestSave?.());

      if (!saveRequested) {
        toast({
          title: 'Save requested',
          description: 'Editor was not ready for force-save. Trying refresh anyway.',
        });
      }

      const ready = await waitForCoverLetterProcessing({
        packageId: effectivePackageId,
        docName: coverLetterEditingName,
        baselineVersion: baseline?.version,
        baselineUpdatedAt: baseline?.updatedAt,
      });

      if (!ready) {
        toast({
          title: 'Still processing',
          description: 'Save is taking longer than expected. Refreshed with latest available data.',
        });
      }

      await refreshExistingPackageDocuments();
      setCoverLetterEditorOpen(false);
    } catch (e) {
      toast({
        title: 'Refresh failed',
        description: e?.message || 'Could not sync updated cover letter.',
        variant: 'destructive',
      });
    } finally {
      setClosingCoverLetterEditor(false);
    }
  };

