  const getMaxFilesForDoc = (doc) => {
    const explicitMaxFiles = Number(doc?.max_files ?? doc?.maxFiles);
    if (Number.isFinite(explicitMaxFiles) && explicitMaxFiles > 0) return explicitMaxFiles;

    const docName = String(doc?.name || '').toLowerCase();
    if (isOxfordRec && docName.includes('uk local information pack') && docName.includes('oid / mcta')) {
      return Infinity;
    }

    const typeKey = getDocTypeKey(doc);
    // Custom document sections or unrecognized types should allow multiple files by default
    if (!typeKey) return Infinity;
    const maxFiles = DOCUMENT_UPLOAD_RULES?.[typeKey]?.maxFiles;
    return Number.isFinite(maxFiles) ? maxFiles : maxFiles === Infinity ? Infinity : 1;
  };

  const getHelperTextForDoc = (doc) => {
    const maxFiles = getMaxFilesForDoc(doc);
    if (maxFiles === 1) return "Only 1 file allowed";
    return "Multiple files allowed";
  };

